/**
 * GitHub Node - Version 1
 * Discriminator: resource=release, operation=create
 */


interface Credentials {
  githubApi: CredentialReference;
  githubOAuth2Api: CredentialReference;
  githubAppApi: CredentialReference;
}

/** Create a new pull request */
export type GithubV1ReleaseCreateParams = {
  resource: 'release';
  operation: 'create';
  authentication?: 'accessToken' | 'oAuth2' | 'githubAppApi' | Expression<string>;
/**
 * Repository Owner
 * @searchListMethod getUsers
 * @default {"mode":"list","value":""}
 */
    owner?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * Repository Name
 * @searchListMethod getRepositories
 * @default {"mode":"list","value":""}
 */
    repository?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * The tag of the release
 */
    releaseTag: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** The name of the issue
     */
    name?: string | Expression<string>;
    /** The body of the release
     */
    body?: string | Expression<string>;
    /** Whether to create a draft (unpublished) release, "false" to create a published one
     * @default false
     */
    draft?: boolean | Expression<boolean>;
    /** Whether to point out that the release is non-production ready
     * @default false
     */
    prerelease?: boolean | Expression<boolean>;
    /** Specifies the commitish value that determines where the Git tag is created from. Can be any branch or commit SHA. Unused if the Git tag already exists. Default: the repository's default branch(usually master).
     */
    target_commitish?: string | Expression<string>;
  };
};

export type GithubV1ReleaseCreateNode = {
  type: 'n8n-nodes-base.github';
  version: 1;
  config: NodeConfig<GithubV1ReleaseCreateParams> & { credentials?: Credentials };
};